with with_windows as (select id, customer_id, device, browser, row_number() over (partition by to_date(started_at), device order by started_at desc, id) as seq_no, row_number() over (partition by to_date(started_at), country order by started_at desc, id) as row_seq, row_number() over (order by started_at desc, id) as event_seq, first_value(browser, true) over (partition by country order by started_at, id rows between unbounded preceding and current row) as first_known_browser from sessions) select s.id, s.customer_id, s.device, s.browser, s.seq_no, s.event_seq, s.first_known_browser, case when browser rlike '^(Chrome|Edge)$' then 'GROUP_A' else 'GROUP_B' end as browser_zone, (select max(t2.monthly_fee) from subscriptions t2 where t2.customer_id = s.customer_id) as max_subscription_monthly_fee from with_windows s order by event_seq nulls last;
